import type { DrawerCompactProps, DrawerCompactEmits, DrawerCompactSlots, DrawerUi } from '@vean/aria/drawer';
import type { ClassValue } from '@vean/aria/types';
import type { ThemeSize } from '@/theme';

/**
 * Properties for the Drawer component.
 */
export type DrawerProps = DrawerCompactProps & {
  /**
   * the popup class of the drawer
   */
  class?: ClassValue;
  /**
   * Visual size of the component.
   */
  size?: ThemeSize;
  /**
   * Per-slot class overrides for the component.
   */
  ui?: Partial<DrawerUi>;
};

/**
 * Events for the Drawer component.
 */
export type DrawerEmits = DrawerCompactEmits;

/**
 * Slots for the Drawer component.
 */
export type DrawerSlots = DrawerCompactSlots;

export { default as SDrawer } from './drawer.vue';

export type * from '@vean/aria/drawer';
export type * from './types';

// @unocss-include
import { scv } from '@soybeanjs/cva';
import { sheetVariants } from './sheet';

export const drawerVariants = scv({
  extend: [sheetVariants],
  slots: {
    handle: `mx-auto shrink-0 cursor-grab active:cursor-grabbing rounded-full bg-muted`,
    swipeArea: 'fixed z-40 touch-none',
    indent: [
      `relative transition-[transform,border-radius] duration-500 [transition-timing-function:cubic-bezier(0.32,0.72,0,1)]`,
      `data-[active]:translate-y-[calc(var(--vean-drawer-swipe-progress,0)*0.5rem_+_0.25rem)]`,
      `data-[active]:scale-[calc(1_-_var(--vean-drawer-swipe-progress,0)*0.05_-_0.02)]`,
      `data-[active]:rounded-b-2xl`
    ],
    indentBackground: 'fixed inset-0 z-40 bg-popover'
  },
  variants: {
    size: {
      xs: {
        handle: 'mt-0.625 h-1.5 w-20'
      },
      sm: {
        handle: 'mt-0.75 h-1.75 w-22'
      },
      md: {
        handle: 'mt-1 h-2 w-25'
      },
      lg: {
        handle: 'mt-1.25 h-2.5 w-30'
      },
      xl: {
        handle: 'mt-1.5 h-3 w-35'
      },
      '2xl': {
        handle: 'mt-1.75 h-3.5 w-40'
      }
    },
    side: {
      top: {
        swipeArea: 'inset-x-0 top-0 h-4'
      },
      bottom: {
        swipeArea: 'inset-x-0 bottom-0 h-4'
      },
      left: {
        swipeArea: 'inset-y-0 start-0 w-4'
      },
      right: {
        swipeArea: 'inset-y-0 end-0 w-4'
      }
    }
  },
  defaultVariants: {
    size: 'md',
    side: 'bottom'
  }
});

export * from './config';
export * from './use-theme-settings';
export * from './use-theme-variants';

export type * from './types';
export { buildThemeCss } from './adapter';

// @unocss-include
import { scv } from '@soybeanjs/cva';
import { dialogVariants } from './dialog';

/**
 * The popup position is fully CSS-variable driven: the Aria gesture layer
 * writes `--vean-drawer-snap-point-offset` (resting snap position) and
 * `--vean-drawer-swipe-movement-x/y` (live drag), and this transform plus a
 * transform transition turns every snap change or release into a CSS animation.
 * The `animate-in`/`animate-out` keyframes only define `from`/`to`, so open and
 * close slide to and from the variable-driven resting position seamlessly.
 *
 * Vertical panels clamp the translate at the viewport edge: a drag that pushes
 * the popup past its resting edge (e.g. upwards on a bottom sheet) would lift
 * the anchored edge and expose the overlay through a gap, so the overflow is
 * applied to `height` instead — the popup grows past its resting size with the
 * same square-root damping and springs back through the height transition.
 *
 * The class strings below are written out in full on purpose: UnoCSS extracts
 * tokens from raw source text, so interpolated template literals are never
 * picked up and their rules would silently vanish from the stylesheet.
 */
const POPUP_TRANSFORM_VERTICAL_BOTTOM =
  '[transform:translateY(max(0px,calc(var(--vean-drawer-snap-point-offset,0px)_+_var(--vean-drawer-swipe-movement-y,0px))))_scale(var(--vean-drawer-nested-scale,1))]';
const POPUP_TRANSFORM_VERTICAL_TOP =
  '[transform:translateY(min(0px,calc(var(--vean-drawer-snap-point-offset,0px)_+_var(--vean-drawer-swipe-movement-y,0px))))_scale(var(--vean-drawer-nested-scale,1))]';
const POPUP_HEIGHT_GROWTH_BOTTOM =
  '[height:calc(var(--vean-drawer-height,auto)_+_max(0px,calc(-1_*_var(--vean-drawer-snap-point-offset,0px)_-_var(--vean-drawer-swipe-movement-y,0px))))]';
const POPUP_HEIGHT_GROWTH_TOP =
  '[height:calc(var(--vean-drawer-height,auto)_+_max(0px,calc(var(--vean-drawer-snap-point-offset,0px)_+_var(--vean-drawer-swipe-movement-y,0px))))]';
const POPUP_TRANSFORM_HORIZONTAL =
  '[transform:translateX(calc(var(--vean-drawer-snap-point-offset,0px)_+_var(--vean-drawer-swipe-movement-x,0px)))_scale(var(--vean-drawer-nested-scale,1))]';
const POPUP_TRANSITION =
  '[transition:transform_0.5s_cubic-bezier(0.32,0.72,0,1),height_0.5s_cubic-bezier(0.32,0.72,0,1),opacity_0.5s_cubic-bezier(0.32,0.72,0,1)]';
/**
 * `dvh` follows the mobile browser chrome as it hides and shows, so it keeps a
 * bottom sheet's top edge on screen while the address bar animates. Browsers
 * without it (Chrome < 108, older WebViews) drop the whole declaration instead
 * of falling back on their own, which leaves the panel uncapped and taller than
 * the screen. The `@supports not` guard makes exactly one of the two win, so
 * newer browsers keep the `dvh` behaviour.
 *
 * A snap-point drawer replaces the viewport cap with its largest snap point: a
 * resting position is reached by translating the box down, so a box taller than
 * the largest snap leaves its far edge below the viewport, hiding the end of the
 * scrolling content from every snap level. Both declarations therefore read the
 * same variable, which equals when it is set — the `@supports` guard only has to
 * disambiguate the fallback.
 */
const POPUP_VIEWPORT_MAX_HEIGHT =
  'max-h-[var(--vean-drawer-max-height,calc(100dvh-2rem))] [@supports(not_(height:100dvh))]:max-h-[var(--vean-drawer-max-height,calc(100vh-2rem))]';
/** The horizontal counterpart, used by the `start`/`end` sides. */
const POPUP_VIEWPORT_MAX_WIDTH = 'max-w-[var(--vean-drawer-max-width,100%)]';
/**
 * Fullscreen, driven by the Aria `data-fullscreen` attribute, has to be
 * re-declared here: this recipe drops the inherited dialog `popup` slot
 * (`extendIgnore`), so the dialog's `data-[fullscreen]:*` rules never reach the
 * panel. Every per-side dimension needs an override, because each side sizes the
 * panel from its own edge:
 *
 * - vertical panels (`top`/`bottom`) are capped by `POPUP_VIEWPORT_MAX_HEIGHT`
 *   and sized by the gesture height growth, so here `height` is pinned and
 *   `max-height` released. `100dvh` follows the mobile browser chrome exactly
 *   like the resting cap does, with the same `@supports` fallback for engines
 *   that cannot parse it.
 * - horizontal panels (`start`/`end`) are already full height, but `w-3/4` plus
 *   `sm:max-w-sm` and `POPUP_VIEWPORT_MAX_WIDTH` keep them narrow.
 * - the anchored corner radius would leave two rounded corners floating inside
 *   the viewport, so it is reset as well.
 *
 * `data-[fullscreen]:*` compiles to a `[data-fullscreen]`-qualified selector, so
 * it outranks the side, `sm:` and arbitrary-property utilities by specificity —
 * the overrides win wherever UnoCSS happens to order them.
 */
const POPUP_FULLSCREEN = [
  `data-[fullscreen]:w-full data-[fullscreen]:max-w-none`,
  `data-[fullscreen]:h-[100dvh] data-[fullscreen]:max-h-none`,
  `[@supports(not_(height:100dvh))]:data-[fullscreen]:h-[100vh]`,
  `data-[fullscreen]:rounded-none`
];

export const sheetVariants = scv({
  extend: [dialogVariants],
  // The drawer redefines both slots: the popup drives its position from the
  // gesture CSS vars, and the overlay tracks the swipe progress with a
  extendIgnore: ['popup'],
  slots: {
    popup: [
      `fixed z-base flex flex-col justify-between items-stretch border bg-popover outline-none`,
      POPUP_TRANSITION,
      ...POPUP_FULLSCREEN,
      `data-[state=open]:animate-in data-[state=open]:duration-500`,
      `data-[state=closed]:animate-out data-[state=closed]:duration-300`
    ]
  },
  variants: {
    size: {
      xs: {
        popup: `gap-y-1.5 px-2 py-1.5 text-2xs`
      },
      sm: {
        popup: `gap-y-2 px-3 py-2 text-xs`
      },
      md: {
        popup: `gap-y-3 px-4 py-3 text-sm`
      },
      lg: {
        popup: `gap-y-4 px-5 py-4 text-base`
      },
      xl: {
        popup: `gap-y-5 px-6 py-5 text-lg`
      },
      '2xl': {
        popup: `gap-y-6 px-7 py-6 text-xl`
      }
    },
    side: {
      top: {
        // Vertical panels are anchored to one edge, so their height must be capped:
        // without a cap a long body grows past the viewport and the `overflow-auto`
        // content slot never scrolls.
        popup: [
          `inset-x-0 top-0 ${POPUP_VIEWPORT_MAX_HEIGHT} origin-top border-b rounded-b-md`,
          POPUP_TRANSFORM_VERTICAL_TOP,
          POPUP_HEIGHT_GROWTH_TOP,
          `data-[state=open]:slide-in-from-top data-[state=closed]:slide-out-to-top`
        ]
      },
      bottom: {
        popup: [
          `inset-x-0 bottom-0 ${POPUP_VIEWPORT_MAX_HEIGHT} origin-bottom border-t rounded-t-md`,
          POPUP_TRANSFORM_VERTICAL_BOTTOM,
          POPUP_HEIGHT_GROWTH_BOTTOM,
          `data-[state=open]:slide-in-from-bottom data-[state=closed]:slide-out-to-bottom`
        ]
      },
      left: {
        popup: [
          `inset-y-0 start-0 h-full origin-left sm:max-w-sm w-3/4 border-e rounded-e-md ${POPUP_VIEWPORT_MAX_WIDTH}`,
          POPUP_TRANSFORM_HORIZONTAL,
          `data-[state=open]:slide-in-from-left data-[state=closed]:slide-out-to-left`,
          `[&[dir=rtl]]:data-[state=open]:slide-in-from-right [&[dir=rtl]]:data-[state=closed]:slide-out-to-right`
        ]
      },
      right: {
        popup: [
          `inset-y-0 end-0 h-full origin-right sm:max-w-sm w-3/4 border-s rounded-s-md ${POPUP_VIEWPORT_MAX_WIDTH}`,
          POPUP_TRANSFORM_HORIZONTAL,
          `data-[state=open]:slide-in-from-right data-[state=closed]:slide-out-to-right`,
          `[&[dir=rtl]]:data-[state=open]:slide-in-from-left [&[dir=rtl]]:data-[state=closed]:slide-out-to-left`
        ]
      }
    }
  },
  defaultVariants: {
    size: 'md',
    side: 'right'
  }
});

import { THEME_SIZE } from '@vean/theme';
import type { ThemeSize } from './types';

/**
 * px value per size preset. The table lives in `@vean/theme` (it drives the
 * density tokens on the engine side); the UI layer maps it to its own name so
 * the two layers can never disagree on what `md` means.
 */
export const themeSizeMap: Record<ThemeSize, number> = THEME_SIZE;
export const miniSizeMap: Record<ThemeSize, ThemeSize> = {
  xs: 'xs',
  sm: 'xs',
  md: 'sm',
  lg: 'md',
  xl: 'lg',
  '2xl': 'xl'
};

export const themeSizeRatio = Object.fromEntries(
  Object.entries(themeSizeMap).map(([key, value]) => [key, value / themeSizeMap.md])
) as Record<ThemeSize, number>;

import { computed, ref } from 'vue';
import type { ComputedRef, Ref } from 'vue';
import { DEFAULT_OPTIONS } from '@vean/theme';
import type { ThemeModePreference, ThemeOptions, ThemeOverrides } from '@vean/theme';
import { readThemeEnvelope, writeThemeEnvelope, THEME_STORAGE_KEY } from '@vean/theme/storage';

/** the editable theme settings state: engine options plus the mode preference. */
export type ThemeSettingsState = ThemeOptions & { mode?: ThemeModePreference };

/**
 * Options for `useThemeSettings`.
 */
export interface UseThemeSettingsOptions {
  /**
   * The initial configuration. When omitted and `persist` is enabled, the
   * persisted envelope is read from storage.
   */
  initial?: ThemeSettingsState;
  /**
   * Whether to read/write the persisted theme envelope from storage.
   *
   * Off by default: inside an `SConfigProvider` tree the provider owns the
   * single envelope writer, and `apply` hands the state to the runtime. Enable
   * it only for standalone usage without a provider.
   *
   * @default false
   */
  persist?: boolean;
  /**
   * The localStorage key backing the persisted envelope.
   *
   * @default THEME_STORAGE_KEY
   */
  storageKey?: string;
  /**
   * The callback invoked by `commit()` to apply the config to the runtime
   * (e.g. `useTheme().setThemeState`).
   */
  apply?: (state: ThemeSettingsState) => void;
}

/**
 * The return value of `useThemeSettings`.
 */
export interface UseThemeSettingsReturn {
  /** The complete writable config (engine options + mode preference). */
  state: Ref<ThemeSettingsState>;
  /** Immutably patch the config (single field or object). */
  setState: (patch: Partial<ThemeSettingsState>) => void;
  /** The editable light/dark single-token overrides. */
  overrides: ComputedRef<ThemeOverrides>;
  /**
   * Set or clear a single override token. Empty values are removed.
   *
   * The key is a token name owned by the engine (`SemanticToken`); it stays a
   * plain `string` here so the settings layer does not encode the vocabulary,
   * and the persisted payload is validated field by field anyway.
   */
  setOverride: (mode: 'light' | 'dark', key: string, value: string) => void;
  /** The engine options derived from `state` (mode stripped), ready for the engine. */
  resolved: ComputedRef<ThemeOptions>;
  /** Persist the config (when `persist`) and call `apply` to push it to the runtime. */
  commit: () => void;
  /** Reset to the engine defaults and clear overrides. */
  reset: () => void;
}

const hasAnyOverride = (overrides: ThemeOverrides | undefined): boolean =>
  overrides != null && (Object.keys(overrides.light ?? {}).length > 0 || Object.keys(overrides.dark ?? {}).length > 0);

/**
 * The UI-layer theme configuration state core.
 *
 * Owns the editable settings state (base/primary/feedback/levels/surface
 * style/size/radius/spacing/overrides/mode), immutable `setState`/`setOverride`
 * updates, and the engine options derived from the state. Used by the theme
 * customizer; pure logic and storage, no component rendering.
 */
export function useThemeSettings(options: UseThemeSettingsOptions = {}): UseThemeSettingsReturn {
  const { initial, persist = false, storageKey = THEME_STORAGE_KEY, apply } = options;

  const persisted = persist && !initial ? readThemeEnvelope(storageKey) : null;
  const state = ref<ThemeSettingsState>({
    ...(persisted ? { ...persisted.options, ...(persisted.mode ? { mode: persisted.mode } : {}) } : undefined),
    ...initial
  });

  const setState = (patch: Partial<ThemeSettingsState>): void => {
    state.value = { ...state.value, ...patch };
  };

  const overrides = computed<ThemeOverrides>(
    () =>
      state.value.overrides ?? {
        light: {},
        dark: {}
      }
  );

  /**
   * set or clear one override value.
   *
   * The value stays a plain `string`: this layer deliberately does not encode the
   * `TokenOverride` vocabulary (`stone.950` / `oklch(...)` / `white` / `token.primary` …),
   * because the values come from pickers and inputs, and the engine's own parser
   * decides what a value means. The write therefore asserts into the narrower
   * `ThemeOverrides` — validation lives in `parseOverrides`, not here.
   */
  const setOverride = (mode: 'light' | 'dark', key: string, value: string): void => {
    const current: ThemeOverrides = state.value.overrides ?? {
      light: {},
      dark: {}
    };
    const modeTokens = { ...current[mode] } as Record<string, string>;

    if (value === '') {
      // eslint-disable-next-line @typescript-eslint/no-dynamic-delete
      delete modeTokens[key];
    } else {
      modeTokens[key] = value;
    }

    const next = { ...current, [mode]: modeTokens } as ThemeOverrides;

    if (!hasAnyOverride(next)) {
      setState({ overrides: undefined });
      return;
    }

    setState({ overrides: next });
  };

  const resolved = computed<ThemeOptions>(() => {
    const { mode: _mode, ...rest } = state.value;

    return rest;
  });

  const commit = (): void => {
    if (persist) {
      // read-modify-write: standalone usage must not drop the style snapshot or
      // the presets the provider may have written into the same envelope
      const envelope = readThemeEnvelope(storageKey);

      writeThemeEnvelope({ ...envelope, options: resolved.value, mode: state.value.mode }, storageKey);
    }

    apply?.(state.value);
  };

  const reset = (): void => {
    state.value = {
      base: DEFAULT_OPTIONS.base,
      primary: DEFAULT_OPTIONS.primary,
      feedback: DEFAULT_OPTIONS.feedback,
      surfaceStyle: DEFAULT_OPTIONS.surfaceStyle,
      size: DEFAULT_OPTIONS.size,
      radius: DEFAULT_OPTIONS.radius,
      spacing: DEFAULT_OPTIONS.spacing,
      // 字体回到引擎默认系统栈（LITERAL_DEFAULTS）
      font: undefined,
      borderOpacity: DEFAULT_OPTIONS.borderOpacity,
      format: DEFAULT_OPTIONS.format,
      mode: 'light',
      overrides: undefined
    };
  };

  return {
    state,
    setState,
    overrides,
    setOverride,
    resolved,
    commit,
    reset
  };
}

import { computed } from 'vue';
import type { ComputedRef, Ref, WritableComputedRef } from 'vue';
import { resolveThemeMap, valueRef } from '@vean/theme';
import type { ColorValue, SemanticToken, TokenValue } from '@vean/theme';
import type { UseThemeSettingsReturn } from './use-theme-settings';

/**
 * the variant group keys a token can belong to.
 */
export type VariantGroupKey = 'surfaces' | 'fills' | 'hairlines' | 'brand' | 'sidebar' | 'feedback' | 'charts';

/**
 * the metadata of a single variant token.
 */
export interface VariantTokenMeta {
  /** the color token key. */
  key: SemanticToken;
  /** the group this token belongs to. */
  group: VariantGroupKey;
  /** the derivation source: base / primary / scheme. */
  source: 'base' | 'primary' | 'scheme';
  /** whether the token follows the background-shade (light/dark level) offset. */
  shadeLinked?: boolean;
  /** a label key used for display (falls back to the token key itself). */
  i18n: string;
}

/**
 * a variant group: its label and the tokens it contains.
 */
export interface VariantGroupMeta {
  /** the group key. */
  key: VariantGroupKey;
  /** the group label key. */
  i18n: string;
  /** the tokens in this group. */
  tokens: VariantTokenMeta[];
}

/**
 * Options for `useThemeVariants`.
 */
export interface UseThemeVariantsOptions {
  /** the settings state core exposing `state` / `setOverride` / `resolved`. */
  settings: UseThemeSettingsReturn;
  /** the active light/dark mode used to select the derived tokens. */
  mode: Ref<'light' | 'dark'>;
  /** optional custom group list; defaults to the built-in variant groups. */
  groups?: VariantGroupMeta[];
}

/**
 * The return value of `useThemeVariants`.
 */
export interface UseThemeVariantsReturn {
  /** the variant groups (group → tokens). */
  groups: VariantGroupMeta[];
  /** the derived tokens from the left-column generator (the resolved preset). */
  derived: ComputedRef<Record<SemanticToken, string>>;
  /** a writable ref bound to the override for a token key. */
  getOverride: (key: SemanticToken) => WritableComputedRef<string>;
  /** merge rule: override wins when present, otherwise falls back to derived (`token.*` refs resolve to a colour form for the picker). */
  final: ComputedRef<Record<SemanticToken, ColorValue>>;
  /** whether the active mode has any explicit override. */
  hasOverrides: ComputedRef<boolean>;
  /** clear the override for a token key. */
  clearOverride: (key: SemanticToken) => void;
}

